import{_ as p,a0 as d,w as r,s as o,ao as l,I as t,x as s,a1 as i,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const m=JSON.parse('{"title":"如何在 Linux 上安裝 Java | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 上安裝 Java | LCTT (201911) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 上安裝 Java | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 上安裝 Java | LCTT (201911) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201911/20191120 How to install Java on Linux","title":"如何在 Linux 上安裝 Java","tag":"201911","desc":""},"relativePath":"201911/20191120 How to install Java on Linux.md","filePath":"[post].md"}'),h={name:"201911/20191120 How to install Java on Linux.md"};function u(c,a,k,b,g,v){const e=d("Link");return r(),o("div",null,[a[23]||(a[23]=l('<h1 id="如何在-linux-上安裝-java" tabindex="-1">如何在 Linux 上安裝 Java <a class="header-anchor" href="#如何在-linux-上安裝-java" aria-label="Permalink to “如何在 Linux 上安裝 Java”">​</a></h1><blockquote><p>在桌面上擁抱 Java 應用程序，然後在所有桌面上運行它們。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/201911/26/065307hk22caubakkos0u0.jpg" alt=""></p><p>無論你運行的是哪種操作系統，通常都有幾種安裝應用程序的方法。有時你可能會在應用程序商店中找到一個應用程序，或者使用 Fedora 上的 DNF 或 Mac 上的 Brew 這樣的軟件包管理器進行安裝，而有時你可能會從網站上下載可執行文件或安裝程序。因為 Java 是這麼多流行的應用程序的後端，所以最好了解安裝它的不同方法。好消息是你有很多選擇，本文涵蓋了所有這些內容。</p><p>壞消息是 Java <em>太大</em>，我説的不僅僅是文件大小。Java 是一種開放源代碼語言和規範，這意味着從理論上講，任何人都可以創建它的實現版本。這意味着，在安裝任何東西之前，必須確定要安裝的 Java 發行版。</p><h3 id="我需要-jvm-還是-jre-或者-jdk" tabindex="-1">我需要 JVM 還是 JRE 或者 JDK？ <a class="header-anchor" href="#我需要-jvm-還是-jre-或者-jdk" aria-label="Permalink to “我需要 JVM 還是 JRE 或者 JDK？”">​</a></h3><p>Java 大致分為兩個下載類別。<ruby>Java 虛擬機<rt>Java Virtual Machine</rt></ruby>（JVM）是運行時組件；它是使 Java 應用程序能夠在計算機上啓動和運行的“引擎”。它包含在 <ruby>Java 運行時環境<rt>Java Runtime Environment</rt></ruby>（JRE）中。</p><p><ruby>Java 開發工具包<rt>Java Development Kit</rt></ruby>（JDK）是一個開發工具包：你可以將其視為一個車庫，修理工可以坐在那裏進行調整、修理和改進。JDK 包含 Java 運行時環境（JRE）。</p><p>以下載來説，這意味着：</p><ul><li>如果你是希望運行 Java 應用程序的用户，則只需 JRE（包括了 JVM）。</li><li>如果你是希望使用 Java 進行編程的開發人員，則需要 JDK（包括 JRE 庫，而 JRE 庫又包括 JVM）。</li></ul><h3 id="openjdk、icedtea-和-oraclejdk-有什麼不同" tabindex="-1">OpenJDK、IcedTea 和 OracleJDK 有什麼不同？ <a class="header-anchor" href="#openjdk、icedtea-和-oraclejdk-有什麼不同" aria-label="Permalink to “OpenJDK、IcedTea 和 OracleJDK 有什麼不同？”">​</a></h3><p>當<ruby>太陽微系統<rt>Sun Microsystems</rt></ruby>被 Oracle 收購時，Java 是該交易的主要部分。幸運的是，Java 是一種開源技術，因此，如果你對 Oracle 維護該項目的方式不滿意，則可以選擇其他方法。Oracle 將專有組件與 Java 下載捆綁在一起，而 OpenJDK 項目是完全開源的。</p><p>IcedTea 項目本質上是 OpenJDK，但其目標是使用户在使用完全自由開源的工具時更容易構建和部署 OpenJDK。</p><p>（LCTT 譯註：阿里巴巴也有一個它自己維護的 Open JDK 發行版“<ruby>龍井<rt>Dragonwell</rt></ruby>”。以下引自其官網：“Alibaba Dragonwell 是一款免費的，生產就緒型 Open JDK 發行版，提供長期支持，包括性能增強和安全修復。……Alibaba Dragonwell 作為 Java 應用的基石，支撐了阿里經濟體內所有的 Java 業務。Alibaba Dragonwell 完全兼容 Java SE 標準，……”）</p><h3 id="我應該安裝哪個-java" tabindex="-1">我應該安裝哪個 Java？ <a class="header-anchor" href="#我應該安裝哪個-java" aria-label="Permalink to “我應該安裝哪個 Java？”">​</a></h3><p>如果你對這些選擇感到不知所措，那麼簡單的答案就是你應該安裝的 Java 實現應該是最容易安裝的那個。當應用程序告訴你需要 Java 12，但你的存儲庫中只有 Java 8 時，可以安裝可以從可靠來源中找到的 Java 12 的任何實現。在 Linux 上，你可以一次安裝幾個不同版本的 Java，它們不會互相干擾。</p>',16)),t("p",null,[a[1]||(a[1]=s("如果你是需要選擇使用哪個版本的開發人員，則應考慮所需的組件。如果選擇 Oracle 的版本，請注意，軟件包中包含專有的插件和字體，可能會",-1)),i(e,{href:"https://www.oracle.com/technetwork/java/javase/overview/oracle-jdk-faqs.html"},{default:n(()=>[...a[0]||(a[0]=[s("影響你分發你的應用程序",-1)])]),_:1}),a[2]||(a[2]=s("。在 IcedTea 或 OpenJDK 上進行開發是最安全的。",-1))]),a[24]||(a[24]=l(`<h3 id="從存儲庫安裝-openjdk" tabindex="-1">從存儲庫安裝 OpenJDK？ <a class="header-anchor" href="#從存儲庫安裝-openjdk" aria-label="Permalink to “從存儲庫安裝 OpenJDK？”">​</a></h3><p>現在，你已經知道要選擇什麼了，你可以使用軟件包管理器搜索 OpenJDK 或 IcedTea，然後安裝所需的版本。有些發行版使用關鍵字 <code>latest</code> 來指示最新版本，這通常是你要運行的應用程序所需要的。根據你使用的軟件包管理器，你甚至可以考慮使用 <code>grep</code> 過濾搜索結果以僅包括最新版本。例如，在 Fedora 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf search openjdk | grep latest | cut -f1 -d&#39;:&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>java-latest-openjdk-demo.x86_64</span></span>
<span class="line"><span>java-openjdk.i686</span></span>
<span class="line"><span>java-openjdk.x86_64</span></span>
<span class="line"><span>java-latest-openjdk-jmods.x86_64</span></span>
<span class="line"><span>java-latest-openjdk-src.x86_64</span></span>
<span class="line"><span>java-latest-openjdk.x86_64</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>只有當你嘗試運行的應用程序堅持要求你使用 Java 的舊版本時，你才應該看看 <code>latest</code> 之前的版本。</p><p>在 Fedora 或類似系統上安裝 Java：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install java-latest-openjdk</span></span></code></pre></div><p>如果你的發行版不使用 <code>latest</code> 標籤，則可以使用其他關鍵字，例如 <code>default</code>。以下是在 Debian 上搜索 OpenJDK 的信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt search openjdk | less</span></span>
<span class="line"><span>default-jdk</span></span>
<span class="line"><span>  Standard Java development kit</span></span>
<span class="line"><span></span></span>
<span class="line"><span>default-jre</span></span>
<span class="line"><span>  Standard Java runtime</span></span>
<span class="line"><span></span></span>
<span class="line"><span>openjdk-11-jdk</span></span>
<span class="line"><span>  OpenJDK development kit (JDK)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>在這種情況下，<code>default-jre</code> 軟件包適合用户，而 <code>default-jdk</code> 則適合開發人員。</p><p>例如，要在 Debian 上安裝 JRE：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install default-jre</span></span></code></pre></div><p>現在已安裝好 Java。</p><p>你的存儲庫中可能有<em>許多</em>與 Java 相關的軟件包。要搜索 OpenJDK，如果你是用户，則查找最新的 JRE 或 JVM，如果你是開發人員，則查找最新的 JDK。</p><h3 id="從互聯網上安裝-java" tabindex="-1">從互聯網上安裝 Java <a class="header-anchor" href="#從互聯網上安裝-java" aria-label="Permalink to “從互聯網上安裝 Java”">​</a></h3>`,14)),t("p",null,[a[5]||(a[5]=s("如果在存儲庫中找不到 JRE 或 JDK，或者找不到滿足你需求的 JRE 或 JDK，則可以從互聯網上下載開源的 Java 軟件包。你可以在 ",-1)),i(e,{href:"http://openjdk.java.net"},{default:n(()=>[...a[3]||(a[3]=[s("openjdk.java.net",-1)])]),_:1}),a[6]||(a[6]=s(" 中找到需要手動安裝的 tar 形式的 OpenJDK 下載文件，或者可以從 Azul 下載 tar 形式的 ",-1)),i(e,{href:"https://www.azul.com/downloads/zulu-community"},{default:n(()=>[...a[4]||(a[4]=[s("Zulu 社區版",-1)])]),_:1}),a[7]||(a[7]=s("或其可安裝的 RPM 或 DEB 軟件包。",-1))]),a[25]||(a[25]=l(`<h4 id="從-tar-文件安裝-java" tabindex="-1">從 TAR 文件安裝 Java <a class="header-anchor" href="#從-tar-文件安裝-java" aria-label="Permalink to “從 TAR 文件安裝 Java”">​</a></h4><p>如果從 Java.net 或 Azul 下載 TAR 文件，則必須手動安裝。這通常稱為“本地”安裝，因為你沒有將 Java 安裝到“全局”位置。你可以在 <code>PATH</code> 中選擇一個合適的位置。</p><p>如果你不知道 <code>PATH</code> 中包含什麼，請查看一下以找出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo $PATH</span></span>
<span class="line"><span>/usr/local/bin:/usr/local/sbin:/usr/bin:/usr/sbin:/home/seth/bin</span></span></code></pre></div><p>在此示例 <code>PATH</code> 中，位置 <code>/usr/local/bin</code> 和 <code>/home/seth/bin</code> 是不錯的選擇。如果你是計算機上的唯一用户，那麼你自己的家目錄就很有意義。如果你的計算機上有很多用户，則最好選擇一個通用位置，例如 <code>/usr/local</code> 或 <code>/opt</code>。</p><p>如果你無權訪問需要 <code>sudo</code> 權限的 <code>/usr/local</code> 之類的系統級目錄，則可以在你自己的家目錄中創建一個本地 <code>bin</code>（意思是 “<ruby>二進制<rt>binary</rt></ruby>”，而不是“<ruby>垃圾箱<rt>waste bin</rt></ruby>”）或 <code>Applications</code> 文件夾：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir ~/bin</span></span></code></pre></div><p>如果它不在你的 <code>PATH</code> 中，請將其添加到其中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo PATH=$PATH:$HOME/bin &amp;gt;&amp;gt; ~/.bashrc</span></span>
<span class="line"><span>$ source ~/.bashrc</span></span></code></pre></div><p>最後，將壓縮包解壓縮到你選擇的目錄中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tar --extract --file openjdk*linux-x64_bin.tar.gz --directory=$HOME/bin</span></span></code></pre></div><p>Java 現在安裝好了。</p><h4 id="從-rpm-或-deb-安裝-java" tabindex="-1">從 RPM 或 DEB 安裝 Java <a class="header-anchor" href="#從-rpm-或-deb-安裝-java" aria-label="Permalink to “從 RPM 或 DEB 安裝 Java”">​</a></h4><p>如果從 Azul.com 下載 RPM 或 DEB 文件，則可以使用軟件包管理器進行安裝。</p><p>對於 Fedora、CentOS、RHEL 等，請下載 RPM 並使用 DNF 進行安裝：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install zulu*linux.x86_64.rpm</span></span></code></pre></div><p>對於 Debian、Ubuntu、Pop_OS 和類似發行版，請下載 DEB 軟件包並使用 Apt 安裝它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dpkg -i zulu*linux_amd64.deb</span></span></code></pre></div><p>Java 現在安裝好了。</p><h4 id="用-alternatives-安裝你的-java-版本" tabindex="-1">用 alternatives 安裝你的 Java 版本 <a class="header-anchor" href="#用-alternatives-安裝你的-java-版本" aria-label="Permalink to “用 alternatives 安裝你的 Java 版本”">​</a></h4><p>一些應用程序是為特定版本的 Java 開發的，不能與其他任何版本一起使用。這種情況很少見，但確實會發生，在 Linux 上，你可以使用本地安裝方法（請參閲上面“從 TAR 文件安裝 Java”一節）或使用 <code>alternatives</code> 應用程序來解決此衝突。</p><p><code>alternatives</code> 命令會查找 Linux 系統上安裝的應用程序，並讓你選擇要使用的版本。有些發行版，例如 Slackware，不提供 <code>alternatives</code> 命令，因此你必須使用本地安裝方法。在 Fedora、CentOS 和類似的發行版上，該命令是 <code>alternatives</code>。在 Debian、Ubuntu 和類似的系統上，該命令是 <code>update-alternatives</code>。</p><p>要獲取當前已安裝在 Fedora 系統上的應用程序的可用版本列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ alternatives --list</span></span></code></pre></div><p>在 Debian 上，你必須指定可供替代的應用程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ update-alternatives --list java</span></span></code></pre></div><p>在 Fedora 上選擇要使系統將哪個版本作為默認版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo alternatives --config java</span></span></code></pre></div><p>在 Debian 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo updates-alternatives --config java</span></span></code></pre></div><p>你可以根據需要運行的應用程序，根據需要更改默認的 Java 版本。</p><h3 id="運行-java-應用" tabindex="-1">運行 Java 應用 <a class="header-anchor" href="#運行-java-應用" aria-label="Permalink to “運行 Java 應用”">​</a></h3><p>Java 應用程序通常以 JAR 文件的形式分發。根據你安裝 Java 的方式，你的系統可能已經為運行 Java 應用程序配置好了，這使你只需雙擊應用程序圖標（或從應用程序菜單中選擇它）即可運行。如果必須執行未與系統其餘部分集成的本地 Java 安裝，則可以直接從終端啓動 Java 應用程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ java -jar ~/bin/example.jar &amp;</span></span></code></pre></div><h3 id="java-是個好東西" tabindex="-1">Java 是個好東西 <a class="header-anchor" href="#java-是個好東西" aria-label="Permalink to “Java 是個好東西”">​</a></h3><p>Java 是少數將跨平台開發放在首位的編程環境之一。沒有什麼比問一個應用程序是否能在你的平台上運行然後發現該應用程序是用 Java 編寫要讓人感到鬆一口氣的了。它是如此簡單，無論你是開發人員還是用户，你都可以擺脱任何平台上的焦慮。在桌面上擁抱 Java 應用程序，然後在<em>所有</em>桌面上運行它們吧。</p><hr>`,37)),t("p",null,[a[9]||(a[9]=s("via: ",-1)),i(e,{href:"https://opensource.com/article/19/11/install-java-linux"},{default:n(()=>[...a[8]||(a[8]=[s("https://opensource.com/article/19/11/install-java-linux",-1)])]),_:1})]),t("p",null,[a[14]||(a[14]=s("作者：",-1)),i(e,{href:"https://opensource.com/users/seth"},{default:n(()=>[...a[10]||(a[10]=[s("Seth Kenlon",-1)])]),_:1}),a[15]||(a[15]=s(" 選題：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:n(()=>[...a[11]||(a[11]=[s("lujun9972",-1)])]),_:1}),a[16]||(a[16]=s(" 譯者：",-1)),i(e,{href:"https://github.com/wxy"},{default:n(()=>[...a[12]||(a[12]=[s("wxy",-1)])]),_:1}),a[17]||(a[17]=s(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:n(()=>[...a[13]||(a[13]=[s("wxy",-1)])]),_:1})]),t("p",null,[a[20]||(a[20]=s("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...a[18]||(a[18]=[s("LCTT",-1)])]),_:1}),a[21]||(a[21]=s(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:n(()=>[...a[19]||(a[19]=[s("Linux中國",-1)])]),_:1}),a[22]||(a[22]=s(" 榮譽推出",-1))])])}const j=p(h,[["render",u]]);export{m as __pageData,j as default};
